"""Compares the minimal graphs generated by `generate` with the ones in `data`, up to isomorphism.

    python -m minimal_graphs.compare [GENERATED_DIR]

Only the orders that were generated are compared. Exits with status 1 if some
graph is missing on either side.
"""
import collections
import csv
import glob
import os
import re
import sys

from minimal_graphs.classify import canonical_form_of_graph6
from minimal_graphs.generate import DEFAULT_OUTPUT_DIR, THINNESS, PROPER_THINNESS

DATA_DIR = 'data'
# Examples printed of each difference.
MAX_EXAMPLES = 5


def compare(generated_dir: str) -> bool:
    """Whether both have the same minimal graphs, printing the counts of each parameter, value and order."""
    max_order = _max_generated_order(generated_dir)
    print(f'Comparing orders up to {max_order}')
    same = True
    for parameter in (THINNESS, PROPER_THINNESS):
        expected = _read_lists(DATA_DIR, parameter, max_order)
        generated = _read_lists(generated_dir, parameter, max_order)
        for value in sorted(expected.keys() | generated.keys()):
            for order in range(1, max_order + 1):
                expected_forms = expected[value][order]
                generated_forms = generated[value][order]
                if not expected_forms and not generated_forms:
                    continue
                missing = expected_forms.keys() - generated_forms.keys()
                extra = generated_forms.keys() - expected_forms.keys()
                status = 'OK' if not missing and not extra else f'{len(missing)} missing, {len(extra)} extra'
                print(f'{parameter} {value}, order {order}: {len(expected_forms):,} in {DATA_DIR}, {len(generated_forms):,} generated, {status}')
                for form in list(missing)[:MAX_EXAMPLES]:
                    print(f'    missing: {expected_forms[form]}')
                for form in list(extra)[:MAX_EXAMPLES]:
                    print(f'    extra: {generated_forms[form]}')
                same = same and not missing and not extra
    return same


def _max_generated_order(generated_dir: str) -> int:
    orders = [
        int(re.fullmatch(r'order-(\d+)\.json', os.path.basename(path)).group(1))
        for path in glob.glob(os.path.join(generated_dir, 'order-*.json'))
    ]
    if not orders:
        raise ValueError(f'Nothing generated in {generated_dir}')
    return max(orders)


def _read_lists(directory: str, parameter: str, max_order: int) -> dict[int, dict[int, dict[int, str]]]:
    """For each value and order, the graph6 of each minimal graph, keyed by canonical form."""
    lists = collections.defaultdict(lambda: collections.defaultdict(dict))
    for path in glob.glob(os.path.join(directory, f'{parameter}-*.csv')):
        value = int(re.fullmatch(rf'{parameter}-(\d+)\.csv', os.path.basename(path)).group(1))
        with open(path, newline='') as file:
            for row in csv.DictReader(file):
                order, form = canonical_form_of_graph6(row['graph6'].encode())
                if order <= max_order:
                    lists[value][order][form] = row['graph6']
    return lists


if __name__ == '__main__':
    sys.exit(0 if compare(sys.argv[1] if len(sys.argv) > 1 else DEFAULT_OUTPUT_DIR) else 1)
